#!/usr/bin/env python3
"""Regenerate docs/design/display_pinout.md from docs/design/display_contract.json."""
import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parents[1]
d = json.loads((ROOT / 'docs/design/display_contract.json').read_text())
lines = ['# Display project pinout', '',
         'Generated by `tools/write_display_pinout.py` from [display_contract.json](display_contract.json). '
         'Manufacturer facts remain in docs/components. J301 rows are panel flex positions; the FH34SRJ footprint '
         'numbers its pads in the same panel order.', '',
         '| Ref | Physical pin | Function | Project net | Treatment |', '|---|---|---|---|---|']
for c in d['components']:
    for p in c['pins']:
        lines.append(f"| {c['ref']} | {p['number']} | {p.get('name', p['number'])} | {p['net'] or '—'} | {p.get('treatment', 'connected')} |")
(ROOT / 'docs/design/display_pinout.md').write_text('\n'.join(lines) + '\n')
print('wrote display_pinout.md', len(lines) - 6, 'rows')
